function initNavbar() {
const navbar = document.getElementById('navbar');
let lastScroll = 0;
window.addEventListener('scroll', () => {
const currentScroll = window.pageYOffset;
if (currentScroll > 20) {
navbar.classList.add('scrolled');
} else {
navbar.classList.remove('scrolled');
}
lastScroll = currentScroll;
});
}
function initMobileMenu() {
const toggle = document.getElementById('navToggle');
const navLinks = document.getElementById('navLinks');
toggle.addEventListener('click', () => {
toggle.classList.toggle('active');
navLinks.classList.toggle('active');
document.body.style.overflow = navLinks.classList.contains('active') ? 'hidden' : '';
});
navLinks.querySelectorAll('a').forEach(link => {
link.addEventListener('click', () => {
toggle.classList.remove('active');
navLinks.classList.remove('active');
document.body.style.overflow = '';
});
});
}
function initScrollReveal() {
const reveals = document.querySelectorAll('.reveal');
const observerOptions = {
threshold: 0.1,
rootMargin: '0px 0px -50px 0px'
};
const observer = new IntersectionObserver((entries) => {
entries.forEach((entry, index) => {
if (entry.isIntersecting) {
const delay = Array.from(entry.target.parentElement.children)
.filter(child => child.classList.contains('reveal'))
.indexOf(entry.target) * 100;
setTimeout(() => {
entry.target.classList.add('visible');
}, delay);
observer.unobserve(entry.target);
}
});
}, observerOptions);
reveals.forEach(el => observer.observe(el));
}
function initCounters() {
const counters = document.querySelectorAll('.counter');
const observerOptions = {
threshold: 0.1,
rootMargin: '0px 0px 0px 0px'
};
const observer = new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
animateCounter(entry.target);
observer.unobserve(entry.target);
}
});
}, observerOptions);
counters.forEach(counter => {
observer.observe(counter);
});
}
function animateCounter(element) {
const target = parseInt(element.getAttribute('data-target'));
const suffix = element.getAttribute('data-suffix') || '+';
const duration = 2000;
const startTime = performance.now();
function update(currentTime) {
const elapsed = currentTime - startTime;
const progress = Math.min(elapsed / duration, 1);
const eased = 1 - Math.pow(1 - progress, 3);
const currentValue = Math.round(target * eased);
element.textContent = currentValue + (progress < 1 ? '' : suffix);
if (progress < 1) {
requestAnimationFrame(update);
}
}
requestAnimationFrame(update);
}
function initSmoothScroll() {
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
anchor.addEventListener('click', function (e) {
e.preventDefault();
const targetId = this.getAttribute('href');
if (targetId === '#') return;
const targetElement = document.querySelector(targetId);
if (targetElement) {
const navHeight = document.getElementById('navbar').offsetHeight;
const targetPosition = targetElement.getBoundingClientRect().top + window.pageYOffset - navHeight;
window.scrollTo({
top: targetPosition,
behavior: 'smooth'
});
}
});
});
}
function initParallaxGlow() {
const glows = document.querySelectorAll('.bg-glow');
window.addEventListener('mousemove', (e) => {
const x = e.clientX / window.innerWidth;
const y = e.clientY / window.innerHeight;
glows.forEach((glow, index) => {
const speed = (index + 1) * 15;
const offsetX = (x - 0.5) * speed;
const offsetY = (y - 0.5) * speed;
glow.style.transform = `translate(${offsetX}px, ${offsetY}px)`;
});
});
}
function openBookingModal() {
const modal = document.getElementById('bookingModal');
modal.classList.add('active');
document.body.style.overflow = 'hidden';
document.getElementById('formContent').classList.remove('hide');
document.getElementById('formSuccess').classList.remove('show');
}
function closeBookingModal() {
const modal = document.getElementById('bookingModal');
modal.classList.remove('active');
document.body.style.overflow = '';
}
document.getElementById('bookingModal').addEventListener('click', (e) => {
if (e.target === e.currentTarget) {
closeBookingModal();
}
});
document.addEventListener('keydown', (e) => {
if (e.key === 'Escape') {
closeBookingModal();
}
});
